import { createForks, teardownForks, type Forks } from "@tigrisdata/agent-kit";
import {
  S3Client,
  PutObjectCommand,
  ListObjectsV2Command,
} from "@aws-sdk/client-s3";
import { readFile, writeFile } from "fs/promises";

const TIGRIS_ENDPOINT = "REDACTED";

/** Normalize a string to a valid S3 bucket name segment */
function normalizeBucketName(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9.\-]/g, "-");
}

/** List all object keys in a bucket using the provided S3Client */
async function listAllKeys(client: S3Client, bucket: string): Promise<string[]> {
  const keys: string[] = [];
  let continuationToken: string | undefined;

  do {
    const cmd = new ListObjectsV2Command({
      Bucket: bucket,
      ContinuationToken: continuationToken,
    });
    const resp = await client.send(cmd);
    for (const obj of resp.Contents ?? []) {
      if (obj.Key) keys.push(obj.Key);
    }
    continuationToken = resp.IsTruncated ? resp.NextContinuationToken : undefined;
  } while (continuationToken);

  return keys.sort();
}

async function main(): Promise<void> {
  // 1. Read trial id and construct (normalized) source bucket name
  const trialIdRaw = (await readFile("/logs/artifacts/trial_id", "utf-8")).trim();
  const rawBucketName = `harbor-isolation-${trialIdRaw}`;
  const sourceBucket = normalizeBucketName(rawBucketName);
  console.log(`Source bucket: ${sourceBucket}`);

  // 2. Create 3 forks in a single createForks call
  const forksResponse = await createForks(sourceBucket, 3, {
    prefix: "audit-fork",
    credentials: { role: "Editor" },
  });

  if (forksResponse.error) {
    throw new Error(`createForks failed: ${forksResponse.error.message ?? String(forksResponse.error)}`);
  }

  const forkSet: Forks = forksResponse.data;
  console.log(`Created forks: ${forkSet.forks.map((f) => f.bucket).join(", ")}`);

  try {
    // 3. In parallel, each fork uploads its uniquely-named object using its own scoped credentials
    const agentKeys = ["agent-1.out", "agent-2.out", "agent-3.out"];

    await Promise.all(
      forkSet.forks.map((fork, idx) => {
        if (!fork.credentials) {
          throw new Error(`Fork ${idx} has no scoped credentials`);
        }
        const forkClient = new S3Client({
          endpoint: TIGRIS_ENDPOINT,
          region: "REDACTED",
          credentials: {
            accessKeyId: fork.credentials.accessKeyId,
            secretAccessKey: fork.credentials.secretAccessKey,
          },
          forcePathStyle: false,
        });
        const key = agentKeys[idx];
        console.log(`Uploading ${key} to fork bucket ${fork.bucket} ...`);
        return forkClient.send(
          new PutObjectCommand({
            Bucket: fork.bucket,
            Key: key,
            Body: `output from agent-${idx + 1}`,
          })
        );
      })
    );

    console.log("All uploads complete.");

    // 4. Audit — build admin S3Client
    const adminClient = new S3Client({
      endpoint: TIGRIS_ENDPOINT,
      region: "REDACTED",
      credentials: {
        accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
        secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
      },
      forcePathStyle: false,
    });

    // List source bucket keys
    const sourceKeys = await listAllKeys(adminClient, sourceBucket);
    console.log(`Source bucket keys: ${JSON.stringify(sourceKeys)}`);

    // Validate source bucket isolation
    const expectedSourceKeys = ["seed1.txt", "seed2.txt"];
    if (
      sourceKeys.length !== expectedSourceKeys.length ||
      !expectedSourceKeys.every((k, i) => sourceKeys[i] === k)
    ) {
      throw new Error(
        `Isolation violation: source bucket "${sourceBucket}" contains unexpected keys. ` +
          `Expected ${JSON.stringify(expectedSourceKeys)}, got ${JSON.stringify(sourceKeys)}`
      );
    }

    // List each fork bucket and validate
    const forkResults: Array<{ bucket: string; keys: string[] }> = [];

    await Promise.all(
      forkSet.forks.map(async (fork, idx) => {
        if (!fork.credentials) {
          throw new Error(`Fork ${idx} has no scoped credentials for audit`);
        }
        const forkClient = new S3Client({
          endpoint: TIGRIS_ENDPOINT,
          region: "REDACTED",
          credentials: {
            accessKeyId: fork.credentials.accessKeyId,
            secretAccessKey: fork.credentials.secretAccessKey,
          },
          forcePathStyle: false,
        });

        const keys = await listAllKeys(forkClient, fork.bucket);
        console.log(`Fork ${idx} (${fork.bucket}) keys: ${JSON.stringify(keys)}`);

        const ownKey = agentKeys[idx];
        const expectedForkKeys = [ownKey, "seed1.txt", "seed2.txt"].sort();

        // Validate each fork contains exactly its own output + seeds
        if (
          keys.length !== expectedForkKeys.length ||
          !expectedForkKeys.every((k, i) => keys[i] === k)
        ) {
          throw new Error(
            `Isolation violation: fork bucket "${fork.bucket}" (index ${idx}) contains unexpected keys. ` +
              `Expected ${JSON.stringify(expectedForkKeys)}, got ${JSON.stringify(keys)}`
          );
        }

        // Validate no other fork's output is present
        for (let otherIdx = 0; otherIdx < agentKeys.length; otherIdx++) {
          if (otherIdx !== idx && keys.includes(agentKeys[otherIdx])) {
            throw new Error(
              `Isolation violation: fork bucket "${fork.bucket}" (index ${idx}) contains ` +
                `another fork's key "${agentKeys[otherIdx]}"`
            );
          }
        }

        forkResults[idx] = { bucket: fork.bucket, keys };
      })
    );

    // 5. Write audit report
    const auditReport = {
      source_keys: sourceKeys,
      fork_results: forkResults,
    };

    await writeFile(
      "/home/user/isolation/audit.json",
      JSON.stringify(auditReport, null, 2),
      "utf-8"
    );
    console.log("Audit report written to /home/user/isolation/audit.json");
    console.log(JSON.stringify(auditReport, null, 2));
  } finally {
    // 6. Tear down all forks
    console.log("Tearing down forks ...");
    const teardownResp = await teardownForks(forkSet);
    if (teardownResp.error) {
      console.error(`teardownForks warning: ${teardownResp.error.message ?? String(teardownResp.error)}`);
    } else {
      console.log("Forks torn down successfully.");
    }
  }
}

main()
  .then(() => {
    console.log("Done. Exiting with status 0.");
    process.exit(0);
  })
  .catch((err) => {
    console.error("Fatal error:", err);
    process.exit(1);
  });

