import { S3Client, CreateBucketCommand, PutObjectCommand, HeadBucketCommand, PutBucketVersioningCommand } from "@aws-sdk/client-s3";
import { readFile } from "fs/promises";

const ENDPOINT = "REDACTED";

const adminClient = new S3Client({
  endpoint: ENDPOINT,
  region: "REDACTED",
  credentials: {
    accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
    secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
  },
});

async function main() {
  const trialIdRaw = (await readFile("/logs/artifacts/trial_id", "utf-8")).trim();
  const rawBucketName = `harbor-isolation-${trialIdRaw}`;
  const bucketName = rawBucketName.toLowerCase().replace(/[^a-z0-9.\-]/g, "-");
  console.log(`Setting up bucket: ${bucketName}`);

  // Check if bucket exists
  try {
    await adminClient.send(new HeadBucketCommand({ Bucket: bucketName }));
    console.log("Bucket already exists");
  } catch (e: any) {
    if (e.name === "NotFound" || e.$metadata?.httpStatusCode === 404) {
      console.log("Creating bucket...");
      await adminClient.send(new CreateBucketCommand({ 
        Bucket: bucketName,
      }));
      console.log("Bucket created.");
    } else {
      throw e;
    }
  }

  // Enable versioning (enables snapshots)
  try {
    await adminClient.send(new PutBucketVersioningCommand({
      Bucket: bucketName,
      VersioningConfiguration: { Status: "Enabled" },
    }));
    console.log("Versioning enabled.");
  } catch (e) {
    console.warn("Could not enable versioning:", e);
  }

  // Upload seed files
  await adminClient.send(new PutObjectCommand({
    Bucket: bucketName,
    Key: "seed1.txt",
    Body: "seed file 1",
  }));
  console.log("Uploaded seed1.txt");

  await adminClient.send(new PutObjectCommand({
    Bucket: bucketName,
    Key: "seed2.txt",
    Body: "seed file 2",
  }));
  console.log("Uploaded seed2.txt");

  console.log("Setup complete.");
}

main().catch(e => { console.error(e); process.exit(1); });
