  console.log("Removing existing bucket (if any)...");
  const removeResp = await removeBucket(bucketName, { force: true });
  if (removeResp.error) {
    console.log("Remove result:", removeResp.error.message);
  } else {
    console.log("Bucket removed.");
  }

  // Create with snapshots enabled
  console.log("Creating bucket with enableSnapshot: true ...");
  const createResp = await createBucket(bucketName, { enableSnapshot: true });
  if (createResp.error) {
    throw new Error(`Failed to create bucket: ${createResp.error.message}`);
  }
  console.log("Bucket created:", JSON.stringify(createResp.data));

  // Upload seed files using AWS SDK
  const adminClient = new S3Client({
    endpoint: ENDPOINT,
    region: "REDACTED",
