      accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
      secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
    },
  });

  await adminClient.send(new PutObjectCommand({
    Bucket: bucketName,
    Key: "seed1.txt",
    Body: "seed file 1",
  }));
  console.log("Uploaded seed1.txt");

  await adminClient.send(new PutObjectCommand({
    Bucket: bucketName,
    Key: "seed2.txt",
    Body: "seed file 2",
  }));
  console.log("Uploaded seed2.txt");

  // Test snapshot
  console.log("Testing snapshot creation...");
  const snapResp = await createBucketSnapshot(bucketName);
  if (snapResp.error) {
    throw new Error(`Snapshot test failed: ${snapResp.error.message}`);
  }
  console.log("Snapshot created:", snapResp.data.snapshotVersion);

  console.log("Setup complete!");
}

main().catch(e => { console.error(e); process.exit(1); });
