import { S3Client, PutBucketVersioningCommand, HeadBucketCommand, PutObjectCommand } from "@aws-sdk/client-s3";
import { readFile } from "fs/promises";

const ENDPOINT = "REDACTED";

async function main() {
  const trialIdRaw = (await readFile("/logs/artifacts/trial_id", "utf-8")).trim();
  const rawBucketName = `harbor-isolation-${trialIdRaw}`;
  const bucketName = rawBucketName.toLowerCase().replace(/[^a-z0-9.\-]/g, "-");
  console.log(`Bucket: ${bucketName}`);

  const adminClient = new S3Client({
    endpoint: ENDPOINT,
    region: "REDACTED",
    credentials: {
      accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
      secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
    },
  });

  // Check bucket
  try {
    await adminClient.send(new HeadBucketCommand({ Bucket: bucketName }));
    console.log("Bucket exists!");
  } catch(e: any) {
    console.log("Bucket HEAD error:", e.message, e.$metadata?.httpStatusCode);
    // Try creating
    const { createBucket } = await import("@tigrisdata/storage");
    const cr = await createBucket(bucketName, { enableSnapshot: true });
    if (cr.error) throw cr.error;
    console.log("Created bucket");

    // Seed it
    await adminClient.send(new PutObjectCommand({ Bucket: bucketName, Key: "seed1.txt", Body: "seed1" }));
    await adminClient.send(new PutObjectCommand({ Bucket: bucketName, Key: "seed2.txt", Body: "seed2" }));
    console.log("Seeds uploaded");
    return;
  }

  // Try creating snapshot with X-Tigris-Enable-Snapshot header on existing bucket
  // Use PutBucketVersioning with snapshot header  
  const versionCmd = new PutBucketVersioningCommand({
    Bucket: bucketName,
    VersioningConfiguration: { Status: "Enabled" },
  });
  // Add X-Tigris-Snapshot header 
  versionCmd.middlewareStack.add((next: any) => async (args: any) => {
    args.request.headers["X-Tigris-Snapshot"] = "true";
    console.log("Sending with headers:", JSON.stringify(args.request.headers));
    return next(args);
  }, { step: "build" });

  const responseHeaders: Record<string, string> = {};
  versionCmd.middlewareStack.add((next: any) => async (args: any) => {
    const result = await next(args);
    Object.assign(responseHeaders, result.response.headers);
    return result;
  }, { step: "build" });

  try {
    const resp = await adminClient.send(versionCmd);
    console.log("Snapshot response status:", resp.$metadata.httpStatusCode);
    console.log("Response headers:", JSON.stringify(responseHeaders));
  } catch(e: any) {
    console.log("Snapshot error:", e.message);
  }
}

main().catch(e => { console.error(e); process.exit(1); });
